package top.monitorglobal.tv;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public final class MainActivity extends Activity {
 private OfficialUpdater updater;private LinearLayout content;private TextView status;private Button start;private final Handler handler=new Handler(Looper.getMainLooper());private final Runnable refresh=new Runnable(){public void run(){update();handler.postDelayed(this,3000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(52,28,52,36);scroll.addView(content);setContentView(scroll);
  label("MONITOR GLOBAL TV",28,true);label("Versão "+BuildConfig.VERSION_NAME+" · notificações de sismos M6+ e tsunami",18,false);status=label("Conferindo configuração…",16,false);
  button("1 · Permitir exibição sobre outros aplicativos",v->{try{startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException e){try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}catch(ActivityNotFoundException ignored){Prefs.status(this,"Abra as permissões nas configurações do aparelho.");}}});
  start=button("2 · Ativar monitoramento",v->{if(Prefs.get(this).getBoolean("enabled",false)){stopService(new Intent(this,MonitorService.class));Prefs.get(this).edit().putBoolean("enabled",false).apply();update();return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);}Prefs.get(this).edit().putBoolean("enabled",true).apply();launch(MonitorService.START);update();});
  button("Replay · Rever último alerta real em 10 segundos",v->launch(MonitorService.REPLAY));
  button("3 · Testar sismo com indicação de tsunami (fictício)",v->launch(MonitorService.TEST));
  button("4 · Testar revisão M7,2 → M6,9 (fictícia)",v->launch(MonitorService.TEST_REVISION));
  button("5 · Testar aviso de tsunami (fictício)",v->launch(MonitorService.TEST_TSUNAMI));
  button("6 · Testar encerramento de tsunami (fictício)",v->launch(MonitorService.TEST_END));
  button("Testar tsunami sem ameaça (dados fictícios)",v->launch(MonitorService.TEST_NO_THREAT));
  button("7 · Testar sequência completa em 10 segundos (fictícia)",v->launch(MonitorService.TEST_SEQUENCE));
  updater=new OfficialUpdater(this,s->{Prefs.get(this).edit().putString("updateStatus",s).apply();update();});button("Verificar atualização oficial",v->updater.check());
  Switch sound=new Switch(this);sound.setText("Som dos avisos · usa o volume de notificações do aparelho");sound.setTextColor(Color.WHITE);sound.setTextSize(17);sound.setPadding(12,10,12,10);sound.setChecked(Prefs.get(this).getBoolean("sound",true));sound.setOnCheckedChangeListener((v,checked)->Prefs.get(this).edit().putBoolean("sound",checked).apply());content.addView(sound);
  button("Duração: "+Prefs.get(this).getInt("seconds",20)+" segundos",v->{int current=Prefs.get(this).getInt("seconds",20),next=current==15?20:current==20?30:current==30?60:current==60?90:current==90?120:15;Prefs.get(this).edit().putInt("seconds",next).apply();((Button)v).setText("Duração: "+next+" segundos");});
  label("Depois de ativar, volte ao conteúdo que deseja assistir. A faixa não captura os botões do controle e fecha automaticamente.",16,false);
  label("Sismo com tsunami: alterna a cada 8 segundos por pelo menos 32 segundos. Replay guarda somente o último alerta real recebido neste aparelho.",15,false);
  label("Primeira conexão: os eventos existentes viram referência, sem disparar avisos antigos. Consultas a cada 30 segundos. O aparelho precisa continuar ligado e com acesso à internet.",15,false);
  label("A exibição sobre outros aplicativos e a permanência em segundo plano ainda precisam ser testadas nesta TV/Fire Stick. O teste demonstrativo não confirma a chegada de um alerta real.",15,false);
  label("Setas: navegar · OK: selecionar · Voltar: sair da configuração",14,false);
 }
 private void launch(String action){try{startForegroundService(new Intent(this,MonitorService.class).setAction(action));}catch(RuntimeException e){Prefs.status(this,"Não foi possível iniciar. Verifique as permissões do aparelho.");}}
 private TextView label(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(bold?Color.WHITE:Color.rgb(186,209,211));t.setPadding(0,8,0,8);if(bold)t.setTypeface(null,Typeface.BOLD);content.addView(t);return t;}
 private Button button(String s,View.OnClickListener listener){Button b=new Button(this);b.setText(s);b.setTextSize(17);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setOnClickListener(listener);b.setPadding(14,9,14,9);b.setOnFocusChangeListener((v,focused)->{GradientDrawable bg=new GradientDrawable();bg.setColor(Color.rgb(22,44,53));bg.setCornerRadius(10);bg.setStroke(focused?3:1,focused?Color.rgb(121,212,199):Color.rgb(53,78,85));b.setBackground(bg);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,6,0,6);content.addView(b,p);return b;}
 private void update(){if(status==null)return;boolean overlay=Settings.canDrawOverlays(this),enabled=Prefs.get(this).getBoolean("enabled",false);long last=Prefs.get(this).getLong("lastCheck",0);String when=last==0?"Ainda sem consulta confirmada":new SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(new Date(last));status.setText((overlay?"Sobreposição permitida":"Sobreposição não permitida · notificações comuns podem não aparecer na TV")+"\n"+Prefs.get(this).getString("status","Pronto para configurar")+" · "+when+"\n"+Prefs.get(this).getString("updateStatus","Canal oficial do projeto · instalação com sua confirmação"));start.setText(enabled?"Parar monitoramento":"2 · Ativar monitoramento");}
 @Override protected void onDestroy(){if(updater!=null)updater.close();super.onDestroy();}
 @Override protected void onResume(){super.onResume();if(Prefs.get(this).getBoolean("enabled",false))launch(MonitorService.START);handler.post(refresh);}
 @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
